        text=cfg[key];refs=re.findall(r'S\d+',text);refs=list(dict.fromkeys(refs)) or ['S1','S2'];claims.append(dict(id=id,statement=text,classification=kind,as_of=DATE,source_ids=refs,calculation_id='scenario_and_finance_assumptions_v1' if kind=='MODEL_ESTIMATE' else None,confidence='LOW' if kind=='MODEL_ESTIMATE' else 'HIGH'))
