    xs=[x['price'] for x in cases];probs=[x['probability'] for x in cases];ex=calc.expected_price(xs,probs);raw,clipped=calc.band_position(p,xs[0],xs[2]);computed=dict(expected_price=ex,expected_delta_pct=calc.pct_change(ex,p),raw_band_position_pct=raw,display_band_position_pct=clipped,endpoint_rr=calc.endpoint_rr(p,xs[0],xs[2]),market_score=calc.market_score(p,xs[0],xs[2]),own_score=calc.own_score(ex,xs[0],xs[2]),supplemental_score=calc.supplemental_score(p,ex,xs[0],probs[0]))
    base_inputs=cfg['cases'][1];br,bm,bc,bd,bn,*_=base_inputs
