    methods=[dict(method=x,status='USED' if x=='CONDITIONAL_SCENARIO' else 'NOT_APPLICABLE',reason=r) for x,r in [('ENTERPRISE_VALUE_DELTA','個別案件の価値差分を他の案件や資金調達から独立に切り出せないため。'),('CONDITIONAL_SCENARIO','共通の売上・倍率・現金負債・株式数へ条件を反映し再計算できるため。'),('CONSENSUS_REVISION','同時点の独立した市場予想改定データを取得していないため。'),('SAME_COMPANY_EVENT_STUDY','発表に決算や調達等が重なり同社単独イベントの異常リターンを分離していないため。'),('PEER_EVENT_STUDY','同じ資本構成・事業範囲・条件の他社標本を検証していないため。')]]
    catalysts=[]
